// ===========================================================================
// splash_core.h -- the CYDpod startup screen, independent of the display driver
// ===========================================================================
// Yellow screen, wordmark centred a little above the middle. The wordmark is a 4-bit alpha mask
// (splash_logo.h, generated by tools/gen_splash.py) blended between ink and yellow one row at a
// time through a Sink, so there is no frame buffer. A Sink provides:
//   void fill(uint16_t colour);                                  whole screen
//   void row(int x, int y, int n, uint16_t* px);                 n native RGB565 pixels; may modify px
// splash.cpp binds it to TFT_eSPI; tests/splash_test.cpp binds it to a fake framebuffer.
#pragma once

#include <stdint.h>
#include <string.h>
#include "splash_logo.h"

#ifndef pgm_read_byte
#define pgm_read_byte(p) (*(const uint8_t*)(p))
#endif

namespace splash {

constexpr uint8_t YELLOW_R = 0xFF, YELLOW_G = 0xD2, YELLOW_B = 0x1F;   // #FFD21F
constexpr uint8_t INK_R = 0x1D, INK_G = 0x1D, INK_B = 0x1F;            // #1D1D1F

constexpr uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b) {
  return (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}
constexpr uint16_t BACKGROUND = rgb565(YELLOW_R, YELLOW_G, YELLOW_B);  // 0xFE83
constexpr uint16_t INK = rgb565(INK_R, INK_G, INK_B);                  // 0x18E3

struct Layout {
  int x, y, w, h;          // where the mask goes
  const uint8_t* mask;
};

// Landscape when the panel is wider than tall (rotation 1 and 3); portrait otherwise. The wordmark's
// vertical centre sits at 45% of the height, i.e. 5% of the height above the middle.
inline Layout layout(int sw, int sh) {
  const bool land = sw > sh;
  Layout l;
  l.w = land ? SPLASH_LANDSCAPE_W : SPLASH_PORTRAIT_W;
  l.h = land ? SPLASH_LANDSCAPE_H : SPLASH_PORTRAIT_H;
  l.mask = land ? SPLASH_LANDSCAPE : SPLASH_PORTRAIT;
  l.x = (sw - l.w) / 2;
  l.y = sh * 45 / 100 - l.h / 2;
  return l;
}

inline int centreY(int sh) { return sh * 45 / 100; }

constexpr int MAX_ROW = SPLASH_LANDSCAPE_W > SPLASH_PORTRAIT_W ? SPLASH_LANDSCAPE_W : SPLASH_PORTRAIT_W;

template <class Sink>
void render(Sink& s, int sw, int sh) {
  s.fill(BACKGROUND);
  const Layout l = layout(sw, sh);
  uint16_t lut[16];                        // 32 B
  for (int a = 0; a < 16; a++) {
    lut[a] = rgb565((uint8_t)((INK_R * a + YELLOW_R * (15 - a) + 7) / 15),
                    (uint8_t)((INK_G * a + YELLOW_G * (15 - a) + 7) / 15),
                    (uint8_t)((INK_B * a + YELLOW_B * (15 - a) + 7) / 15));
  }
  uint16_t line[MAX_ROW];                  // at most 512 B
  const int stride = (l.w + 1) / 2;
  for (int y = 0; y < l.h; y++) {
    const uint8_t* src = l.mask + y * stride;
    for (int x = 0; x < l.w; x++) {
      const uint8_t b = pgm_read_byte(src + (x >> 1));
      line[x] = lut[(x & 1) ? (b & 15) : (b >> 4)];
    }
    s.row(l.x, l.y + y, l.w, line);
  }
}

// Progress never touches the wordmark or the version label. Sink adds rect() and
// text(text, centreX, topY, font); text uses the existing TFT fonts, size 1.
constexpr uint16_t TRACK = rgb565(0xE0, 0xB4, 0x00);
constexpr uint32_t FRAME_MS = 125, MINIMUM_MS = 600;
struct ProgressLayout { int x, y, w; int textY() const { return y + 12; } };
inline ProgressLayout progressLayout(int sw, int sh) {
  const Layout logo = layout(sw, sh);
  return {sw / 10, logo.y + logo.h + 14, sw - 2 * (sw / 10)};
}
inline int fillWidth(int width, int percent) { return (width * percent + 50) / 100; }
struct Progress {
  char phase[64]{}, detail[48]{};
  uint32_t last = 0, reported = 0;
  int percent = 0;
  bool active = false, warning = false, dirty = true, painted = false, clearDetail = false;
  template<class Sink>
  void tick(Sink& s, int sw, int sh, uint32_t now) {
    if (!active || (painted && uint32_t(now - last) < FRAME_MS)) return;
    last = now; painted = true;
    const auto l = progressLayout(sw, sh);
    s.rect(l.x, l.y, l.w, 6, warning ? BACKGROUND : TRACK);
    if (!warning) {
      // A stale percentage (e.g. merge comparisons) has no measurable length.
      if (percent < 0 || uint32_t(now - reported) >= 250) {
        const int block = l.w / 6;
        const int x = int((now / FRAME_MS) % 16) * (l.w - block) / 15;
        s.rect(l.x + x, l.y, block, 6, INK);
      } else s.rect(l.x, l.y, fillWidth(l.w, percent), 6, INK);
    }
    if (dirty) {
      s.rect(l.x, l.textY(), l.w, 17, BACKGROUND);
      if (clearDetail) s.rect(l.x, l.textY() + 24, l.w, 8, BACKGROUND);
      s.text(phase, sw / 2, l.textY(), 2);
      if (warning) {
        s.rect(l.x, l.textY() + 16, l.w, 1, INK); // readable underline, no low-contrast warn colour
        s.text(detail, sw / 2, l.textY() + 24, 1);
      }
      dirty = false; clearDetail = false;
    }
  }
  template<class Sink>
  void update(Sink& s, int sw, int sh, const char* text, int pc, uint32_t now,
              bool warn = false, const char* extra = "") {
    if (strcmp(phase, text) || strcmp(detail, extra) || warning != warn) dirty = true;
    strncpy(phase, text, sizeof phase - 1); phase[sizeof phase - 1] = 0;
    strncpy(detail, extra, sizeof detail - 1); detail[sizeof detail - 1] = 0;
    percent = pc >= 0 && pc <= 100 ? pc : -1;
    clearDetail = clearDetail || warning || warn;
    reported = now; warning = warn; active = true;
    // Warnings must appear before their blocking dwell/retry delay.
    if (warn) painted = false;
    tick(s, sw, sh, now);
  }
};
static_assert(sizeof(Progress) < 160, "bounded boot state");
}  // namespace splash
